export function CdrLockup({ region = "US", style }: { region?: CdrRegion; style?: CSSProperties }) {
  return region === "CA" ? <LockupCA style={style} /> : <LockupUS style={style} />;
}

export function CdrSymbol({ region = "US", style }: { region?: CdrRegion; style?: CSSProperties }) {
  return region === "CA" ? <SymbolCA style={style} /> : <SymbolUS style={style} />;
}
